import{_ as a,o,c as t,a3 as r}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Interface: DiscoveryOptions","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/port-mapping/src/discover.ts"},"headers":[],"relativePath":"api/tools/@pumpkin-plugins/port-mapping/discover/interfaces/DiscoveryOptions.md","filePath":"docs/api/tools/@pumpkin-plugins/port-mapping/discover/interfaces/DiscoveryOptions.md","lastUpdated":null}'),s={name:"api/tools/@pumpkin-plugins/port-mapping/discover/interfaces/DiscoveryOptions.md"};function p(i,e,n,c,l,d){return o(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../../">@pumpkin-plugins/port-mapping API</a> / <a href="./../">discover</a> / DiscoveryOptions</p><h1 id="interface-discoveryoptions" tabindex="-1">Interface: DiscoveryOptions <a class="header-anchor" href="#interface-discoveryoptions" aria-label="Permalink to &quot;Interface: DiscoveryOptions&quot;">​</a></h1><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/498110a138a4a386a7c0fe70a8d04ba391a856ab/tools/port-mapping/src/discover.ts#L14" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:14</a></p><p>What to look for and where.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="natpmp" tabindex="-1">natPmp <a class="header-anchor" href="#natpmp" aria-label="Permalink to &quot;natPmp&quot;">​</a></h3><blockquote><p><strong>natPmp</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/498110a138a4a386a7c0fe70a8d04ba391a856ab/tools/port-mapping/src/discover.ts#L18" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:18</a></p><p>Look for NAT-PMP gateways.</p><hr><h3 id="natpmpgateway" tabindex="-1">natPmpGateway? <a class="header-anchor" href="#natpmpgateway" aria-label="Permalink to &quot;natPmpGateway?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>natPmpGateway?</strong>: <a href="./../../ipv4/interfaces/Endpoint"><code>Endpoint</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/498110a138a4a386a7c0fe70a8d04ba391a856ab/tools/port-mapping/src/discover.ts#L22" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:22</a></p><p>The NAT-PMP gateway to use. Without it the usual router addresses of the local network are tried.</p><hr><h3 id="screen" tabindex="-1">screen? <a class="header-anchor" href="#screen" aria-label="Permalink to &quot;screen?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>screen?</strong>: <a href="./../../identify/type-aliases/Screen"><code>Screen</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/498110a138a4a386a7c0fe70a8d04ba391a856ab/tools/port-mapping/src/discover.ts#L30" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:30</a></p><p>Turns routers down by what they are. It sees every router that gives away its make and model, before anything is asked of it, and a router it gives a reason for is not used: when that leaves no router, discovery throws a <code>RouterRefusedError</code>. Without it routers are not identified.</p><hr><h3 id="searchms" tabindex="-1">searchMs? <a class="header-anchor" href="#searchms" aria-label="Permalink to &quot;searchMs?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>searchMs?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/498110a138a4a386a7c0fe70a8d04ba391a856ab/tools/port-mapping/src/discover.ts#L24" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:24</a></p><p>How long a UPnP search waits for answers, in milliseconds.</p><hr><h3 id="ssdp" tabindex="-1">ssdp? <a class="header-anchor" href="#ssdp" aria-label="Permalink to &quot;ssdp?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>ssdp?</strong>: <a href="./../../ipv4/interfaces/Endpoint"><code>Endpoint</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/498110a138a4a386a7c0fe70a8d04ba391a856ab/tools/port-mapping/src/discover.ts#L20" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:20</a></p><p>Where to send UPnP searches. Defaults to the SSDP multicast group; a router&#39;s own address works when multicast is blocked.</p><hr><h3 id="upnp" tabindex="-1">upnp <a class="header-anchor" href="#upnp" aria-label="Permalink to &quot;upnp&quot;">​</a></h3><blockquote><p><strong>upnp</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/498110a138a4a386a7c0fe70a8d04ba391a856ab/tools/port-mapping/src/discover.ts#L16" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:16</a></p><p>Look for UPnP gateways.</p>',34)])])}const f=a(s,[["render",p]]);export{u as __pageData,f as default};
